def shipping_cost(weight, express):
    """Return the shipping cost."""
    if weight > 0:
        if express:
            return weight * 3
        else:
            return weight * 2
    else:
        raise ValueError("weight must be positive")

def discount(price, member):
    if price is not None:
        if member:
            return price * 0.9
        else:
            return price
    else:
        return 0
